var diskImage = 'balloon.d64';

function loadFiles() {
  var base64EncodedFile =
    '';

  FS.createDataFile('/', diskImage, window.atob(base64EncodedFile), true, true);
}

function audioDetected() {
  return (
    (typeof Audio === 'function' && new Audio().mozSetup === 'function') ||
    typeof AudioContext === 'function' ||
    typeof webkitAudioContext === 'function'
  );
}

var viceArguments = ['-autostart', diskImage].concat(
  audioDetected()
    ? ['-soundsync', 0, '-soundrate', 22050, '-soundfragsize', 2]
    : ['-sound'],
);
var Module = {
  preRun: [loadFiles],
  arguments: viceArguments,
  canvas: document.getElementById('canvas'),
};
